escenas.animacion:
const ac = A.accent || '#FFD400';
const T19 = A.k('19', 1.0), Tanos = A.k('años…', 1.333), Thoy = A.k('hoy', 2.0), Tmil = A.k('miles', 2.333);
const Tchi = A.k('chilenos', 3.0), Tcam = A.k('caminan', 3.333), Tnoc = A.k('noche', 4.333), Tvis = A.k('visitarla.', 5.0);

A.bg('#0d1a36', '#050a18', true);

// --- noche ---
const pn = A.p(Tnoc - 0.2, 0.8, 'softInOut');
if (pn > 0) {
  A.rect(0, 0, A.W, A.H, { fill: '#01030c', alpha: 0.5 * pn });
  A.particles(45, 7, (i, rnd) => {
    const x = rnd() * A.W, y = 420 + rnd() * 700;
    const tw = 0.5 + 0.5 * Math.sin(t * 3 + i);
    A.circle(x, y, 1.5 + rnd() * 2.5, { fill: '#ffffff', alpha: pn * (0.3 + 0.6 * tw) });
  });
  A.with(() => {
    A.circle(900, 500, 46, { fill: '#f4f1de', glow: 30 });
    A.circle(920, 488, 42, { fill: '#0a1128' });
  }, { alpha: pn, x: 900, y: 500, scale: A.lerp(0.6, 1, pn) });
}

// --- movimiento del 19 hacia la meta ---
const pm = A.p(Thoy - 0.05, 0.75, 'whip');
const numY = A.lerp(740, 560, pm);
const numS = A.lerp(1, 0.4, pm);

// camino serpenteante
const road = [];
for (let i = 0; i <= 60; i++) {
  const s = i / 60;
  road.push([540 + Math.sin(s * Math.PI * 2.5) * 230 * (1 - s * 0.7), 1110 - s * 470]);
}
const pr = A.p(Thoy + 0.1, 0.9, 'glide');
if (pr > 0) {
  const rev = road.slice().reverse();
  A.line(rev, { stroke: '#3a4f80', lw: 34, alpha: 0.6, progress: pr });
  A.line(rev, { stroke: ac, lw: 3, dash: [14, 16], alpha: 0.7, progress: pr });
}

// peregrinos
if (t > Tmil) {
  const N = 46;
  A.particles(N, 21, (i, rnd) => {
    const start = Tmil + i * 0.035;
    if (t < start) return;
    const sp = 0.05 + rnd() * 0.05;
    let u = (rnd() * 0.85 + (t - start) * sp) % 1;
    const side = (rnd() - 0.5) * 26;
    const f = u * 60, i0 = Math.floor(f), i1 = Math.min(60, i0 + 1), fr = f - i0;
    const x = A.lerp(road[i0][0], road[i1][0], fr) + side;
    const y = A.lerp(road[i0][1], road[i1][1], fr);
    const a = Math.min(1, (t - start) * 4, u * 8, (1 - u) * 6);
    const sc = A.lerp(1, 0.6, u);
    const bob = Math.sin(t * 9 + i) * 2;
    A.with(() => {
      A.circle(x, y - 26 + bob, 6, { fill: '#ffffff' });
      A.line([[x, y - 20 + bob], [x, y - 4]], { stroke: '#ffffff', lw: 4 });
      if (pn > 0) A.lib.glowDot(ctx, x + 8, y - 16 + bob, 4, { color: ac });
    }, { alpha: a, x, y, scale: sc });
  });
}

// meta / santuario
if (pm > 0) {
  const pulse = 1 + 0.04 * Math.sin(t * 4);
  A.circle(540, 560, 115 * pm * pulse, { fill: ac, alpha: 0.12 * pm, glow: 40 });
  A.circle(540, 560, 105 * pm, { stroke: ac, lw: 5, alpha: pm });
}
if (t > Tvis - 0.1) {
  A.rings(540, 560, Tvis - 0.1, { count: 3, speed: 260, gap: 0.3, maxR: 300, color: ac, lw: 4 });
  const pl = A.pop(Tvis, 0.45);
  A.label('AUCO', 780, 640, { size: 40, bg: ac, color: '#0a1128', scale: pl });
}

// barra de vida
const lifeA = 1 - A.p(Thoy - 0.1, 0.4, 'accelExit');
if (lifeA > 0) {
  const pb = A.p(0.05, T19 - 0.05, 'cruise');
  const x0 = 190, x1 = 890, yb = 990;
  A.rect(x0, yb - 10, x1 - x0, 20, { r: 10, fill: '#1c2a4d', alpha: lifeA });
  const xe = A.lerp(x0, A.lerp(x0, x1, 19 / 20), pb);
  A.rect(x0, yb - 10, Math.max(20, xe - x0), 20, { r: 10, fill: ac, alpha: lifeA, glow: 18 });
  A.text('1900', x0, yb + 60, { size: 34, color: '#ffffff', align: 'left', alpha: lifeA * 0.8 });
  if (t > T19) {
    const pc = A.pop(T19, 0.4);
    A.with(() => {
      A.line([[xe, yb - 40], [xe, yb + 40]], { stroke: '#ffffff', lw: 6 });
      A.text('1919', xe, yb + 60, { size: 34, color: ac, weight: '800', align: 'center' });
    }, { alpha: lifeA, x: xe, y: yb, scale: pc });
  }
}

// el gran 19
const cnt = t < T19 ? A.counter(0, 19, A.p(0, T19, 'cruise'), 0) : '19';
const hit = t > T19 ? A.pop(T19, 0.4) : 1;
const shake = (t > T19 && t < T19 + 0.25) ? 12 * (1 - (t - T19) / 0.25) : 0;
A.with(() => {
  A.text(cnt, 540, numY + 120, { size: 380, color: ac, weight: '900', align: 'center', stroke: '#050a18', strokeWidth: 10 });
}, { x: 540, y: numY, scale: numS * hit, shake });
if (t > T19 - 0.05) A.flash(T19, 0.25, 0.35);
const aA = A.p(Tanos, 0.4, 'softLand') * lifeA;
if (aA > 0) A.text('AÑOS', 540, 880 + (1 - aA) * 30, { size: 64, color: '#ffffff', weight: '800', align: 'center', alpha: aA });

// zona secundaria: textos
if (t > Tmil) {
  const s1 = A.pop(Tmil, 0.45);
  const txt = t > Tchi ? 'MILES DE CHILENOS' : 'MILES';
  const s1b = t > Tchi ? A.pop(Tchi, 0.4) : s1;
  A.with(() => {
    A.text(txt, 540, 1470, { size: 78, color: '#ffffff', weight: '900', align: 'center' });
  }, { x: 540, y: 1450, scale: s1b });
}
if (t > Tcam) {
  const pc = A.p(Tcam, 0.5, 'softLand');
  const pathW = 360 * pc;
  A.arrow(540 - pathW / 2, 1540, 540 + pathW / 2, 1540, { progress: pc, color: ac, lw: 6, head: 22 });
}
if (t > Tnoc) {
  const s3 = A.pop(Tnoc, 0.45);
  A.label('TODA LA NOCHE', 540, 1640, { size: 56, bg: ac, color: '#0a1128', scale: s3 });
}

const W=A.W, ac=A.accent;
A.bg('#0b1a2e','#04101c');
const kJ=A.k('Juana',0.667), kF=A.k('Fernández',1.0), kS=A.k('Solar',1.333);
const kSan=A.k('Santiago',2.333), k19=A.k('1900',3.0);
const kNad=A.k('nadar',4.0), kCab=A.k('caballo',5.0), kEsc=A.k('escribir',5.667), kDia=A.k('diario',6.333);
const font=(s,w)=>`${w} ${s}px ${A.FONT}`;
function writeT(str,x,y,size,p,color,weight){
  if(p<=0) return;
  ctx.save(); ctx.font=font(size,weight); const w=ctx.measureText(str).width+20;
  ctx.beginPath(); ctx.rect(x-w/2-10,y-size*1.2,(w+20)*p,size*2.4); ctx.clip();
  A.text(str,x,y,{size,color,weight,align:'center'});
  ctx.restore();
}
// ---- DIARIO (protagonista) ----
const open=A.p(0,0.75,'snapSettle');
// atenuación suave y regreso al 100% ANTES de que llegue el lápiz
const dimDown=A.p(kNad-0.2,0.5,'softInOut');
const dimUp=A.p(kEsc-0.6,0.45,'softInOut');
const dim=t<kEsc-0.6 ? A.lerp(1,0.6,dimDown) : A.lerp(0.6,1,dimUp);
const bx=540, by=780, pw=410, ph=600;
const sh19 = (t>k19 && t<k19+0.35) ? 10*(1-(t-k19)/0.35) : 0;
const LX0=bx-pw+30, LX1=bx-50, LY=1045;
const wav=(i)=>LY+Math.sin(i*1.3)*8+Math.sin(i*0.4)*4;
function mapPin(x,tipY,R){
  const cy=tipY-50, d=tipY-cy, phi=Math.acos(R/d);
  ctx.save();
  ctx.beginPath();
  ctx.moveTo(x,tipY);
  ctx.arc(x,cy,R,Math.PI/2+phi,Math.PI/2-phi+Math.PI*2);
  ctx.closePath();
  ctx.fillStyle=ac; ctx.fill();
  ctx.lineWidth=4; ctx.strokeStyle='#ffffff'; ctx.lineJoin='round'; ctx.stroke();
  ctx.beginPath(); ctx.arc(x,cy,R*0.38,0,Math.PI*2); ctx.fillStyle='#10263f'; ctx.fill();
  ctx.lineWidth=3; ctx.strokeStyle='#ffffff'; ctx.stroke();
  ctx.restore();
}
A.with(()=>{
  A.rect(bx-pw-6,by-ph/2,pw,ph,{r:18,fill:'#10263f',stroke:A.pal.lineWhite,lw:4});
  A.rect(bx+6,by-ph/2,pw,ph,{r:18,fill:'#10263f',stroke:A.pal.lineWhite,lw:4});
  A.lib.hatch(ctx,[[bx-pw-6,by-ph/2],[bx-pw+60,by-ph/2],[bx-pw+60,by+ph/2],[bx-pw-6,by+ph/2]],{angle:0.8,spacing:14,width:1.5,color:'rgba(160,200,230,0.18)'});
  A.line([[bx,by-ph/2+10],[bx,by+ph/2-10]],{stroke:A.pal.lineWhite,lw:5});
  for(let i=0;i<8;i++){const yy=by-ph/2+90+i*62;
    A.line([[bx-pw+30,yy],[bx-30,yy]],{stroke:'rgba(140,190,220,0.18)',lw:2});
    A.line([[bx+36,yy],[bx+pw-24,yy]],{stroke:'rgba(140,190,220,0.18)',lw:2});}
  const lx=bx-pw/2-6;
  writeT('Juana',lx,640,84,A.p(kJ,0.35,'cruise'),'#ffffff','700');
  writeT('Fernández',lx,750,66,A.p(kF,0.35,'cruise'),'#ffffff','700');
  writeT('Solar',lx,860,84,A.p(kS,0.35,'cruise'),ac,'800');
  A.line([[lx-140,905],[lx-40,912],[lx+60,900],[lx+150,910]],{stroke:ac,lw:6,progress:A.p(kS+0.3,0.4,'glide')});
  // Santiago: pin de mapa
  const rx=bx+pw/2+6;
  const pin=A.p(kSan-0.15,0.5,'crashIn');
  if(pin>0){
    const tipY=A.lerp(500,645,pin);
    if(pin>=1){
      ctx.save(); ctx.globalAlpha*=0.5; ctx.fillStyle=ac;
      ctx.beginPath(); ctx.ellipse(rx,648,22,6,0,0,Math.PI*2); ctx.fill(); ctx.restore();
      A.rings(rx,648,kSan+0.35,{count:2,speed:120,maxR:90,color:ac,lw:3});
    }
    mapPin(rx,tipY,30);
    A.text('Santiago',rx,705,{size:56,color:'#ffffff',weight:'700',align:'center',alpha:A.p(kSan,0.4,'softLand')});
  }
  // Año: contador 1880 -> 1900, nunca pasa de 1900
  const cStart=k19-0.95;
  if(t>cStart){
    const pc=A.p(cStart,0.85,'glide');
    const yr=String(Math.min(1900,Math.round(A.lerp(1880,1900,A.clamp(pc)))));
    const done=t>=k19;
    const s=done?A.pop(k19,0.45):1;
    A.with(()=>{
      A.text(yr,rx,870,{size:120,color:done?ac:'#ffffff',weight:'900',align:'center',alpha:A.p(cStart,0.2,'softInOut')});
    },{x:rx,y:840,scale:Math.max(s,0.01)});
    if(done){ A.rect(rx-170,780,340,140,{r:20,stroke:ac,lw:5,alpha:A.p(k19,0.3,'crashIn')}); A.rings(rx,850,k19,{count:2,speed:500,maxR:300,color:ac,lw:4}); }
  }
  if(t>kEsc){
    const pts=[]; for(let i=0;i<=40;i++){pts.push([A.lerp(LX0,LX1,i/40),wav(i)]);}
    A.line(pts,{stroke:'#ffffff',lw:4,progress:A.p(kEsc+0.35,0.9,'cruise')});
  }
},{x:bx,y:by,scale:0.55+0.45*open,alpha:open*dim,rot:Math.sin(t*0.9)*0.008,shake:sh19});
A.flash(k19,0.25,0.25);

// ---- GUSTOS ----
const cy=1530, xs=[230,540,850], ks=[kNad,kCab,kEsc], labs=['NADAR','CABALLO','DIARIO'], lk=[kNad,kCab,kDia];
for(let i=0;i<3;i++){
  if(t<ks[i]-0.1) continue;
  const s=A.pop(ks[i]-0.1,0.45);
  A.with(()=>{
    A.circle(xs[i],cy,115,{fill:'#0f2d47',stroke:ac,lw:5,glow:14});
    ctx.save(); ctx.beginPath(); ctx.arc(xs[i],cy,108,0,Math.PI*2); ctx.clip();
    if(i===0){
      for(let j=0;j<3;j++){const pts=[];for(let q=0;q<=24;q++){const x=xs[i]-110+q*9.2;pts.push([x,cy+10+j*30+Math.sin(q*0.7+t*5+j)*9]);}
        A.line(pts,{stroke:j===0?ac:'rgba(77,208,225,0.55)',lw:6});}
      const hy=cy-25+Math.sin(t*5)*6;
      A.circle(xs[i]-10,hy,22,{fill:'#ffffff'});
      A.line([[xs[i]+15,hy+10],[xs[i]+55,hy-30+Math.sin(t*8)*10]],{stroke:'#ffffff',lw:9});
    } else if(i===1){
      const ox=xs[i]-10, oy=cy+Math.sin(t*12)*5;
      ctx.save(); ctx.translate(ox,oy); ctx.beginPath();
      ctx.moveTo(-35,75); ctx.lineTo(-25,5); ctx.quadraticCurveTo(-15,-50,18,-62); ctx.lineTo(28,-88); ctx.lineTo(36,-58);
      ctx.quadraticCurveTo(66,-30,72,5); ctx.lineTo(60,22); ctx.quadraticCurveTo(34,16,18,0); ctx.lineTo(30,75); ctx.closePath();
      ctx.fillStyle=ac; ctx.fill(); ctx.lineWidth=4; ctx.strokeStyle='#ffffff'; ctx.stroke();
      ctx.fillStyle='#0f2d47'; ctx.beginPath(); ctx.arc(38,-35,6,0,Math.PI*2); ctx.fill();
      ctx.restore();
      for(let m=0;m<4;m++) A.line([[ox-22-m*4,oy-45+m*25],[ox-50-m*4+Math.sin(t*10+m)*6,oy-35+m*25]],{stroke:'#ffffff',lw:5});
    } else {
      const dx=xs[i]-8, dy=cy+4;
      A.rect(dx-52,dy-68,104,136,{r:10,fill:ac,stroke:'#ffffff',lw:4});
      A.rect(dx-38,dy-54,70,108,{r:6,fill:'#10263f'});
      for(let r=0;r<4;r++) A.line([[dx-30,dy-34+r*22],[dx+(r===3?0:22),dy-34+r*22]],{stroke:'#ffffff',lw:3});
      A.line([[dx+14,dy-68],[dx+14,dy+80]],{stroke:'#ffffff',lw:4});
      A.rect(dx+38,dy-10,26,22,{r:4,fill:'#ffffff'});
      ctx.save(); ctx.strokeStyle='#ffffff'; ctx.lineWidth=4; ctx.beginPath(); ctx.arc(dx+51,dy-12,8,Math.PI,0); ctx.stroke(); ctx.restore();
      A.circle(dx+51,dy+1,3,{fill:'#0f2d47'});
      ctx.save(); ctx.translate(dx+60,dy+56); ctx.rotate(-0.8);
      ctx.fillStyle='#ffffff'; ctx.fillRect(-6,-70,12,58);
      ctx.fillStyle=ac; ctx.fillRect(-6,-70,12,12);
      ctx.beginPath(); ctx.moveTo(-6,-12); ctx.lineTo(6,-12); ctx.lineTo(0,0); ctx.closePath(); ctx.fillStyle='#ffffff'; ctx.fill();
      ctx.restore();
    }
    ctx.restore();
  },{x:xs[i],y:cy,scale:Math.max(s,0.01)});
  const la=A.p(lk[i],0.35,'softLand');
  if(la>0) A.label(labs[i],xs[i],1695,{size:38,bg:ac,color:'#06121f',scale:A.pop(lk[i],0.4),alpha:la});
}

// ---- PLUMA: sale del icono y escribe en la página izquierda ----
if(t>kEsc){
  const fly=A.p(kEsc,0.38,'whip');
  const wp=A.p(kEsc+0.35,0.9,'cruise');
  const i=Math.round(wp*40), wx=A.lerp(LX0,LX1,i/40), wy=wav(i);
  const px=fly<1?A.lerp(850,wx,fly):wx, py=fly<1?A.lerp(1530,wy,fly):wy;
  A.with(()=>{
    ctx.save(); ctx.translate(px,py); ctx.rotate(-0.7);
    ctx.fillStyle='#ffffff'; ctx.fillRect(-9,-150,18,130);
    ctx.fillStyle=ac; ctx.fillRect(-9,-150,18,30);
    ctx.beginPath(); ctx.moveTo(-9,-20); ctx.lineTo(9,-20); ctx.lineTo(0,0); ctx.closePath(); ctx.fillStyle=ac; ctx.fill();
    ctx.restore();
    A.lib.glowDot(ctx,px,py,10,{color:ac});
  },{alpha:A.p(kEsc,0.15,'softInOut')*(1-A.p(A.dur-0.25,0.25,'accelExit'))});
}

const W=A.W, ac=A.accent, G=1060;
A.bg('#140b26','#05030c');
const k18=A.k('18',0.667), kAnos=A.k('años',1.0), kEntro=A.k('entró',1.333), kConv=A.k('convento',2.333), kCarm=A.k('carmelita',2.667), kAndes=A.k('Andes',3.667), kTomo=A.k('tomó',4.333), kNombre=A.k('nombre',5.0), kTeresa=A.k('Teresa',5.667), kJesus=A.k('Jesús',6.333);

// estrellas ambientales
A.particles(26, 7, (i, r) => {
  const x=r()*W, y=440+r()*300, ph=r()*6;
  const a=0.25+0.35*(0.5+0.5*Math.sin(t*2.2+ph));
  A.circle(x,y,1.5+r()*2,{fill:'#ffffff',alpha:a});
});

// montañas (Los Andes) se alzan detrás
const pM=A.p(kAndes-0.35,0.9,'whip');
if(pM>0){
  ctx.save(); ctx.beginPath(); ctx.rect(0,0,W,G); ctx.clip();
  const off=(1-pM)*560;
  const mp=[[-20,G],[120,700],[230,780],[360,560],[500,740],[620,640],[760,800],[900,560],[1100,760],[1100,G]].map(([x,y])=>[x,y+off]);
  ctx.beginPath(); mp.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y)); ctx.closePath();
  ctx.fillStyle='#24173f'; ctx.fill();
  A.lib.hatch(ctx, mp, {angle:-0.8, spacing:18, width:1.5, color:'rgba(179,136,255,0.30)'});
  A.lib.inkPath(ctx, mp, {width:4, color:'#cdb8ff', closed:true});
  [[360,560],[900,560],[620,640],[120,700]].forEach(([x,y])=>{
    const s=[[x-34,y+40+off],[x,y+off],[x+34,y+40+off],[x+12,y+32+off],[x,y+44+off],[x-14,y+30+off]];
    ctx.beginPath(); s.forEach(([a,b],i)=>i?ctx.lineTo(a,b):ctx.moveTo(a,b)); ctx.closePath();
    ctx.fillStyle='rgba(240,235,255,0.9)'; ctx.fill();
  });
  ctx.restore();
  const sL=A.pop(kAndes);
  if(sL>0) A.label('LOS ANDES', 880, 490, {size:44, bg:'#ffffff', color:'#140b26', scale:sL});
}

// suelo
A.line([[0,G],[W,G]],{stroke:'#cdb8ff', lw:4, progress:A.p(0,0.8,'glide')});

// convento
const pC=A.p(kConv-0.15,1.0,'softLand');
const kIn=kEntro+1.7;
const glow=A.p(kIn,0.4,'softInOut')*0.5 + A.p(kTeresa,0.3,'crashIn')*0.5*(0.8+0.2*Math.sin(t*8));
if(pC>0){
  const body=[[440,800],[760,800],[760,G],[440,G]];
  const roof=[[420,802],[600,680],[780,802]];
  const tower=[[370,640],[450,640],[450,G],[370,G]];
  const troof=[[360,642],[410,575],[460,642]];
  ctx.save(); ctx.globalAlpha=pC;
  [body,tower].forEach(pp=>{ctx.beginPath(); pp.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y)); ctx.closePath(); ctx.fillStyle='#1d1235'; ctx.fill();});
  [roof,troof].forEach(pp=>{ctx.beginPath(); pp.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y)); ctx.closePath(); ctx.fillStyle='#3a2468'; ctx.fill();});
  A.lib.hatch(ctx, body, {angle:0.9, spacing:20, width:1.4, color:'rgba(179,136,255,0.28)'});
  A.lib.hatch(ctx, tower, {angle:0.9, spacing:14, width:1.4, color:'rgba(179,136,255,0.35)'});
  // puerta arco
  ctx.beginPath(); ctx.moveTo(555,G); ctx.lineTo(555,960); ctx.arc(600,960,45,Math.PI,0); ctx.lineTo(645,G); ctx.closePath();
  ctx.fillStyle='#07040f'; ctx.fill();
  if(glow>0){ ctx.save(); ctx.globalAlpha=pC*glow; ctx.shadowColor=ac; ctx.shadowBlur=50; ctx.fillStyle=ac; ctx.fill(); ctx.restore(); }
  // ventanas
  [[490,880],[710,880],[410,720]].forEach(([x,y])=>{ctx.beginPath(); ctx.moveTo(x-16,y+40); ctx.lineTo(x-16,y); ctx.arc(x,y,16,Math.PI,0); ctx.lineTo(x+16,y+40); ctx.closePath(); ctx.fillStyle='rgba(179,136,255,'+(0.25+glow*0.6)+')'; ctx.fill();});
  ctx.restore();
  const lc='#efe6ff';
  A.line([...body,[440,800]],{stroke:lc,lw:4,progress:pC});
  A.line(roof,{stroke:lc,lw:4,progress:pC});
  A.line([...tower,[370,640]],{stroke:lc,lw:4,progress:pC});
  A.line(troof,{stroke:lc,lw:4,progress:pC});
  const pX=A.p(kConv+0.5,0.4,'snapSettle');
  A.line([[410,575],[410,515]],{stroke:ac,lw:7,progress:pX});
  A.line([[388,538],[432,538]],{stroke:ac,lw:7,progress:pX});
  if(pX>0) A.circle(410,538,6,{fill:ac,glow:20,alpha:pX});
}

// carmelita
const sK=A.pop(kCarm);
if(sK>0){
  A.arrow(830,890,770,915,{progress:A.p(kCarm+0.1,0.3,'glide'),color:ac,lw:5});
  A.label('CARMELITA', 900, 870, {size:44, bg:ac, color:'#140b26', scale:sK});
}

// persona que camina y entra
